<section class="hero mb-4"><div><span class="eyebrow">TODO EN UN SOLO LUGAR</span><h1>Encuentra tecnología, hogar y accesorios</h1><p>Explora productos, compara precios y compra con una experiencia moderna de comercio electrónico.</p><a href="#productos" class="btn grad px-4">Ver productos</a></div><div class="hero-stat"><b>Compra simple</b><span>Catálogo → Carrito → Pago → Entrega</span></div></section><div class="row g-4" id="productos"><aside class="col-lg-3"><div class="card p-3 filter-card"><h5>Filtrar productos</h5><form><input type="hidden" name="r" value="catalog"><label>Buscar</label><input class="form-control" name="search" value="<?=e($_GET['search']??'')?>" placeholder="Producto, marca o SKU"><label>Categoría</label><select class="form-select searchable-select" name="category"><option value="">Todas</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($_GET['category']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label>Marca</label><select class="form-select searchable-select" name="brand"><option value="">Todas</option><?php foreach($brands as $b):?><option <?=($_GET['brand']??'')===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select><div class="row g-2"><div class="col"><label>Desde</label><input class="form-control" type="number" name="min" value="<?=e($_GET['min']??'')?>"></div><div class="col"><label>Hasta</label><input class="form-control" type="number" name="max" value="<?=e($_GET['max']??'')?>"></div></div><label>Ordenar</label><select class="form-select searchable-select" name="sort"><option value="new">Más recientes</option><option value="price_asc">Precio menor</option><option value="price_desc">Precio mayor</option><option value="name">Nombre</option></select><button class="btn blue w-100 mt-3">Aplicar filtros</button></form></div></aside><div class="col-lg-9"><div class="d-flex justify-content-between align-items-end mb-3"><div><span class="eyebrow">CATÁLOGO</span><h2 class="section mb-0">Productos destacados</h2></div><span class="text-muted"><?=count($products)?> resultados</span></div><div class="row g-3"><?php foreach($products as $p):$sale=(float)$p['sale_price']>0;?><div class="col-sm-6 col-xl-4"><div class="card product-card p-3"><a href="/?r=product&id=<?=$p['id']?>"><img class="product-img" src="/<?=e($p['image']?:'uploads/images.jpg')?>"></a><div class="d-flex justify-content-between mt-2"><span class="tinybadge"><?=e($p['category'])?></span><?php if($sale):?><span class="sale">OFERTA</span><?php endif;?></div><small class="text-muted"><?=e($p['brand'])?> · <?=e($p['sku'])?></small><h5><a class="product-link" href="/?r=product&id=<?=$p['id']?>"><?=e($p['name'])?></a></h5><?php if($sale):?><div><span class="oldprice">Q<?=number_format($p['price'],2)?></span> <span class="price">Q<?=number_format($p['sale_price'],2)?> <small>/<?=e($p['unit_type']??'unidad')?></small></span></div><?php else:?><div class="price">Q<?=number_format($p['price'],2)?> <small>/<?=e($p['unit_type']??'unidad')?></small></div><?php endif;?><div class="stock <?=$p['stock']<=$p['min_stock']?'low':''?>"><?=$p['stock']>0?'Disponible · '.$p['stock'].' '.($p['unit_type']??'unidades'):'Agotado'?></div><form method="post" action="/?r=add" class="mt-auto"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="qty" value="1"><button class="btn blue w-100" <?=$p['stock']<=0?'disabled':''?>>Agregar al carrito</button></form></div></div><?php endforeach;?></div></div></div><?php require __DIR__.'/../_pagination.php';?>